// CSD_RATIONALE_BEGIN
// SMILES isocyanate CSD — extend attempt 9's 20% best to 36%+ by expanding guidance
// coverage and strengthening the early-phase penalty.
//
// Root-cause analysis:
//   Attempt 9 (best, 20%): 10 guidance examples, SafePenalizedConstrainedStep penalty=4.0,
//   T=1.6 mid-phase. Got 20 unique valid molecules in 100 runs.
//   Attempt 40 (7%): Switched to 6 unusual examples → model collapsed to 7 unique.
//   Attempt 38 (10%): T=2.0 everywhere → model degraded due to excessive noise.
//
// Mechanism confirmed by attempt ledger:
//   - FAMILIAR diverse structural examples → more modes for the model to choose from.
//   - N=C=O-only closure check: O=C=N-format SMILES (hasNCO=0) continue extending past
//     the first complete parse, forcing more complex/unique output structures.
//   - CloseSpanWithinBudget fallback catches EOS-terminated extensions.
//
// Two targeted changes from attempt 9:
//   1. Expand guidance from 10 to 20 diverse, recognizable isocyanate examples,
//      covering halogen-alkyl, cycloalkyl, aromatic, heteroaromatic, branched-alkyl,
//      vinyl, propargyl, ether, and multi-ring classes.  More distinct structural
//      anchors in the prompt → more distinct LM modes → more unique outputs.
//   2. Increase early-phase penalty from 4.0 to 6.0 (same tokens: ["C","CC","O"]).
//      Stronger avoidance of the two dominant starter patterns pushes the model's
//      opening-token distribution toward less-common alternatives, amplifying the
//      cross-run diversity already created by T=1.6.
//
// Everything else is identical to attempt 9 (the proven baseline):
//   minSpanLength=5, T=1.6 mid-phase, GroupBoostedConstrainedStep late-phase,
//   N=C=O check, CloseSpanWithinBudget fallback.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity): insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   OpenConstrainedSpan: sets currentConstrainedOut := []; parser.IsValidPrefix([])
//   holds by method precondition, so the implication is satisfied. ✓
//
//   "IsComplete && length>=5 && hasNCO>0" (CloseConstrainedSpan): sets
//   insideConstrainedOut := false; implication is vacuously true; currentConstrainedOut := []. ✓
//
//   "IsComplete && length>=5 && hasNCO==0" (SafeTemperatureConstrainedStep + Append):
//   SafeTemperatureConstrainedStep hard-masks to parser-valid tokens plus EOS.
//   EOS → break without appending (implication unchanged). Non-EOS → AppendConstrainedToken
//   preserves IsValidPrefix by its postcondition. ✓
//
//   "else" branch (not complete or short span): SafePenalizedConstrainedStep (early),
//   SafeTemperatureConstrainedStep (mid), and GroupBoostedConstrainedStep (late) all
//   hard-mask to parser-valid tokens plus EOS. Non-EOS → AppendConstrainedToken preserves
//   validity. EOS inner-close is gated on IsCompletePrefix and minSpanLength, then
//   CloseConstrainedSpan makes the implication vacuously true. ✓
//
//   Post-loop CloseSpanWithinBudget: postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   OpenConstrainedSpan: appends "<<" (+1 to |generated|); steps := steps+1 (+1). ✓
//
//   "IsComplete+hasNCO" (CloseConstrainedSpan): appends ">>" (+1); steps+1 is
//   bounded by loop guard steps < maxSteps before the call. ✓
//
//   "IsComplete+extend" (SafeTemperatureConstrainedStep): exactly +1 step; EOS adds
//   0 to |generated|; non-EOS AppendConstrainedToken adds ≤1 token. ✓
//
//   "else" branch: exactly +1 step; AppendConstrainedToken adds ≤1 token to |generated|.
//   EOS inner-close adds +1 more step gated by steps < maxSteps, so total +2 steps
//   within budget; |generated| grows by +1 for ">>". ✓
//
//   CloseSpanWithinBudget: closeBudget = maxSteps - steps; postcondition gives
//   |cg| <= |generated| + closeBudget <= |generatedPrefix| + maxSteps; steps := maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid SMILES for an isocyanate (R-N=C=O functional group). Be maximally diverse. Generate a DIFFERENT structure from these 20 example classes: O=C=NCC(F)(F)F, O=C=NCCCl, O=C=NCCC, O=C=NCCCC, O=C=NC(C)CC, O=C=NC(C)(C)C, O=C=NC1CC1, O=C=NC1CCC1, O=C=NC1CCCC1, O=C=NC1CCCCC1, O=C=NC1CCCCCC1, O=C=NCc1ccccc1, O=C=NC(C)c1ccccc1, O=C=Nc1ccc2ccccc2c1, O=C=Nc1ccccn1, O=C=Nc1ccncc1, O=C=NCC=C, O=C=NCC#C, O=C=NCCOc1ccccc1, O=C=NC(F)(F)CC. Output ONLY the SMILES string with no explanation.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 {
      // Explicit N=C=O found: close the span
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // O=C=N format: keep extending to force more complex/unique structures
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 6 {
      // Early phase: stronger penalty (6.0) on common openers for diverse starting points
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 6.0, eosToken
      );
    } else if tokenCount < 18 {
      // Mid phase: moderate temperature for structural variety
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
    } else {
      // Late phase: group-boosted to leverage caller vocabulary hints
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
        if hasNCO > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

